R = sys.argv[1] if len(sys.argv) > 1 else "src/android/app/src/main/res"
LOC = sorted(d for d in os.listdir(R) if d.startswith("values-"))


def esc(t):
    t = t.replace("\\'", "'").replace("'", "\\'")
    return t.replace("&", "&amp;") if "&" in t and "&amp;" not in t else t


ok = 0
for d in LOC:
    code = d[len("values-"):]
    f = os.path.join(R, d, "strings.xml")
    if code == "b+en+GB" or not os.path.exists(f):
        continue
    tr = T.get(code)
    if not tr:
        print("MISSING", code)
        continue
    assert len(tr) == len(KEYS), (code, len(tr))
    s = open(f, encoding="utf-8").read()
    add = ""
    for k, v in zip(KEYS, tr):
        if f'name="{k}"' in s:
            continue
        add += f'    <string name="{k}">{esc(v)}</string>\n'
    if add:
        s = s.replace("</resources>", "\n    <!-- Lighter surfaces and touch input additions -->\n" + add + "</resources>")
        open(f, "w", encoding="utf-8").write(s)
        ok += 1
print("updated", ok)
